public class CoinChangeSolverTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Object few(int[] coins, int amount) {
        try {
            return CoinChangeSolver.minCoins(coins, amount);
        } catch (RuntimeException e) {
            return "threw " + e.getClass().getSimpleName();
        }
    }

    static Object ways(int[] coins, int amount) {
        try {
            return CoinChangeSolver.countWays(coins, amount);
        } catch (RuntimeException e) {
            return "threw " + e.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        check("minCoins({1,5,6,9}, 11) beats greedy", 2, few(new int[] {1, 5, 6, 9}, 11));
        check("minCoins({1,5,10,25}, 63)", 6, few(new int[] {1, 5, 10, 25}, 63));
        check("minCoins({2}, 3) impossible", -1, few(new int[] {2}, 3));
        check("minCoins of 0 is 0", 0, few(new int[] {5}, 0));
        check("minCoins of a negative amount", -1, few(new int[] {1}, -4));
        check("minCoins with no usable coins", -1, few(new int[] {0, -3}, 7));
        check("minCoins with duplicate values", 2, few(new int[] {2, 2, 5}, 4));
        check("minCoins with a big amount", 400, few(new int[] {3, 7}, 2800));

        check("countWays({1,2,5}, 5)", 4L, ways(new int[] {1, 2, 5}, 5));
        check("countWays({1,2,5}, 11)", 11L, ways(new int[] {1, 2, 5}, 11));
        check("countWays ignores order", 1L, ways(new int[] {3}, 9));
        check("countWays of 0 is 1", 1L, ways(new int[] {1, 2}, 0));
        check("countWays of a negative amount", 0L, ways(new int[] {1}, -1));
        check("countWays with duplicate values", 2L, ways(new int[] {2, 2, 5}, 10));
        check("countWays with a null array", 0L, ways(null, 5));
        check("countWays(null, 0) is 1", 1L, ways(null, 0));
        check("countWays on a large amount", 9572962L, ways(new int[] {1, 2, 3, 4, 5}, 400));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
