import java.util.Arrays;
import java.util.TreeSet;

public class CoinChangeSolver {

    public static int minCoins(int[] coins, int amount) {
        if (amount < 0) {
            return -1;
        }
        int[] values = usable(coins);
        int[] best = new int[amount + 1];
        Arrays.fill(best, Integer.MAX_VALUE);
        best[0] = 0;
        for (int target = 1; target <= amount; target++) {
            for (int coin : values) {
                if (coin <= target && best[target - coin] != Integer.MAX_VALUE) {
                    best[target] = Math.min(best[target], best[target - coin] + 1);
                }
            }
        }
        return best[amount] == Integer.MAX_VALUE ? -1 : best[amount];
    }

    public static long countWays(int[] coins, int amount) {
        if (amount < 0) {
            return 0;
        }
        int[] values = usable(coins);
        long[] ways = new long[amount + 1];
        ways[0] = 1;
        for (int coin : values) {
            for (int target = coin; target <= amount; target++) {
                ways[target] += ways[target - coin];
            }
        }
        return ways[amount];
    }

    private static int[] usable(int[] coins) {
        TreeSet<Integer> distinct = new TreeSet<>();
        if (coins != null) {
            for (int coin : coins) {
                if (coin > 0) {
                    distinct.add(coin);
                }
            }
        }
        int[] values = new int[distinct.size()];
        int i = 0;
        for (int coin : distinct) {
            values[i++] = coin;
        }
        return values;
    }
}
